import json
DATA=json.loads('{"timing_feedback": ["Canh lại giờ từ kết quả máy phát", [["Dán WV và End", "Sau khi tạo lịch, bấm Canh lại giờ cạnh Tạo lịch. Dán hai dòng WV và End từ kết quả kiểm tra đúng M3U hiện tại. MINUS là giảm, ADD là thêm. Bấm Canh lại và xuất lịch."], ["Kiểm tra kết quả", "PIP chạy lại bộ cân lịch theo quy tắc hiện có, xuất M3U/QC và báo số giây còn lệch. Có thể chưa tìm được phương án khớp tuyệt đối; kiểm tra M3U mới trên máy phát. Dán lại cùng nội dung không cộng dồn. Lưu riêng theo EP; Bỏ điều chỉnh sẽ dùng mốc gốc."]]], "_ui": {"title": "Hướng dẫn sử dụng PIP", "hint": "Chọn mục cần đọc. Hướng dẫn không thay đổi thông tin EP.", "search": "Tìm hướng dẫn", "close": "Đóng", "subtitle": "Tiếng Việt · Lên lịch, chuẩn bị file và QC"}, "quick": ["Đọc đầu tiên — 3 bước cơ bản", [["1. Copy câu show mở đầu", "Vào bước 0: Nhập thông tin. Copy và dán nguyên câu Next day will air… của EP đang làm."], ["2. Copy thời gian thừa / thiếu đầu ngày", "Dán nguyên dòng thời gian bên dưới câu show mở đầu, gồm giờ End và phần ADD/MINUS nếu có. Giữ nguyên dòng đã nhận, không cần tự tính đổi."], ["3. Bấm Chạy tất cả", "Bấm Chạy tất cả. Nếu hiện bảng thiếu file hoặc cần xác nhận thì xử lý rồi tiếp tục. Chạy xong đọc QC."]]], "start": ["Cài đặt và quy trình đầy đủ", [["Cài đặt", "Giải nén toàn bộ bộ ZIP, rồi mở SCHEDULER.cmd. Giữ nguyên các thư mục đi kèm. Bộ này có file nhẹ để lên lịch; video gốc vẫn lấy ở thư mục nguồn."], ["Trước khi làm", "Kiểm tra truy cập được W:\\\\@ SHOW EXPORTS. Mở INPUT.xlsx, kiểm tra chương trình và ADS đúng ngày, lưu và đóng Excel sau khi sửa."], ["Các bước hằng ngày", "1. Chọn số EP.\\n2. Nhập câu show mở đầu và thời lượng phần còn thiếu.\\n3. Kiểm tra FN, TSER FN, block bắt đầu, lệch đầu ngày và MT shift.\\n4. Bấm Chạy tất cả; xử lý bảng thiếu hoặc cần xác nhận file.\\n5. Xem Cycle 1, Các cycle và QC.\\n6. Bấm Chuẩn bị file khi cần copy video gốc đã đổi tên vào temp của EP nguồn."], ["Chạy tất cả và Chuẩn bị file", "Chạy tất cả tạo EP nhẹ, lịch và QC. Chuẩn bị file copy video gốc vào temp của EP nguồn. Muốn có cả lịch và video gốc đã chuẩn bị thì dùng cả hai chức năng."]]], "prepare": ["Chuẩn bị file / Update / Dừng", [["Chuẩn bị file — Prepare files", "Copy các video gốc đã chọn vào thư mục temp trong EP nguồn, dùng tên local đã duyệt. File đã có ở đích được giữ lại. Thư mục này có thể nặng vì chứa bản copy video gốc."], ["Update cạnh Chuẩn bị file", "Dựa vào lịch sử chuẩn bị để copy nguồn mới hoặc đã thay đổi; bỏ qua nguồn không đổi đã xử lý. Nếu đã xóa file ở temp và cần copy lại, dùng Chuẩn bị file."], ["Dừng chuẩn bị", "Dừng copy và bỏ phần file đang copy dở. Những file đã copy xong vẫn giữ. Xem báo cáo cuối để biết file nào bị bỏ qua và lý do."], ["FN reair", "Bộ FN chọn từ EP trước cũng được copy vào temp của EP đang làm. Tên local dùng số EP hiện tại, giữ thông tin sự kiện, part và REAIR. Tên file nguồn giữ nguyên."]]], "run": ["Chạy tất cả / Quét EP / Tạo EP / Tạo lịch", [["Kết quả lần cuối", "PIP lưu kết quả tạo lịch theo EP, kể cả bản nháp. Mở lại tự hiện EP đã lưu gần nhất, các cycle và QC, không tự chạy lại. Đổi EP sẽ nạp kết quả của EP đó. Bấm Chạy tất cả để có kết quả mới. Các lần chạy trước khi có tính năng này cần tạo lịch một lần để bắt đầu lưu."], ["Chạy tất cả — Run all", "Chạy lần lượt Quét EP → Tạo EP → Tạo lịch → QC. Chọn hoặc xác nhận các file còn vướng trước khi tiếp tục. Chạy xong vẫn cần đọc QC."], ["Quét EP — Scan EP", "Đọc INPUT và file nguồn của EP; hiện tên nguồn, tên local dự kiến và các part tìm được. Quét lại sau khi thay file nguồn hoặc INPUT."], ["Tạo EP — Create EP", "Tạo file nhẹ để lên lịch: có file thật thì lấy thời lượng thật; phần thiếu dùng thời lượng đã nhập. Nếu nguồn đang thay đổi hoặc chưa hoàn chỉnh, bước này có thể dừng và báo lỗi."], ["Tạo lịch — Build schedule", "Sắp các cycle, canh MT và cuối ngày, xuất M3U và QC. Sau khi đổi file hoặc tên, quét và tạo lại EP trước khi tạo lịch."]]], "settings": ["EP / FN / Block bắt đầu / Canh MT", [["EP và Hôm nay", "EP là số ngày đang làm. Hôm nay lấy EP theo ngày hiện tại. Thông tin được nhớ riêng theo EP; câu show mở đầu sai số EP thì cần sửa."], ["FN và TSER FN", "FN bật bộ nội dung FN; TSER FN bật teaser FN. Teaser FN ưu tiên khe giữa NWN S2 và S3, mỗi cycle đầy đủ 2 lần theo NWN; khi canh giờ có thể giảm còn 1. FN reair dùng số EP hiện tại ở tên local."], ["Block bắt đầu và Nhận diện", "Dán câu show mở đầu, bấm Nhận diện để đối chiếu INPUT. Kiểm tra cả số EP và thứ tự chương trình. Block bắt đầu là điểm vào của vòng cycle."], ["Lệch đầu ngày — giây", "Số âm bắt đầu sớm hơn, số dương bắt đầu muộn hơn. Xem thời gian thực tế trong QC."], ["MT shift — số show", "Số dương dời vị trí MT về sau; số âm dời lên trước theo số show. Ví dụ +2 là sau thêm 2 show, không phải thêm 2 phút. Bộ canh giờ vẫn phải tìm cách đạt mốc MT; xem cả giờ và vị trí trong QC."]]], "input": ["Nhập thông tin / Thời lượng / INPUT", [["Bước 0", "Dán câu show mở đầu và thời lượng còn thiếu; bấm Đọc và lưu thông tin. Dữ liệu lưu theo EP. Ô trống không xóa thông tin EP khác đã lưu."], ["Cách ghi thời lượng", "Ghi phút:giây, ví dụ 00:40 là 40 giây; 08:14 là 8 phút 14 giây. Ghi rõ chương trình và part, ví dụ AP PARTD. Có file thật thì ưu tiên thời lượng file thật."], ["Bảng INPUT", "Mở bảng đầu vào để sửa danh sách show và ADS theo ngày. Mở bảng ADS để xem danh mục. Sửa xong lưu bảng rồi Quét EP lại."], ["Thiếu file hoặc sai số EP", "Bảng kiểm tra đầu tiên hiện file thiếu và file đã nhận ra nhưng sai EP. Tick chấp nhận cho EP này nếu đồng ý dùng tên local đã chỉnh. File nguồn không đổi tên. Nguồn bị thay sẽ cần xác nhận lại."]]], "files": ["Chọn file / Bỏ qua / Chọn lại", [["Chọn nhóm ADS", "Bấm Chọn nhóm ADS cạnh Browse, thêm ít nhất 2 file, dùng ↑/↓ sắp thứ tự rồi Lưu nhóm. Lịch tính cả nhóm là một ADS với tổng thời lượng; M3U xuất các file liền nhau. Skip bỏ cả nhóm. Muốn đổi thì mở lại Chọn nhóm ADS; Browse thay nhóm bằng một file. QC M3U báo nếu nhóm thiếu file hoặc sai thứ tự."], ["Files / Skip", "Mở lại các lựa chọn của EP, kể cả file đã tìm được hoặc đã bỏ qua. Muốn đổi lựa chọn cũ thì vào đây."], ["Browse — Chọn file", "Chọn file thay thế cho dòng đang báo. Với bộ FN, chọn P1A để nạp cả bộ tương ứng; kiểm tra danh sách xác nhận để tránh lẫn sự kiện hoặc part."], ["Skip today — Bỏ qua EP này", "Nhớ bỏ qua cho EP này và không dùng mục đó. Chạy tất cả không nhắc lại mục đã bỏ qua. Muốn dùng lại thì mở Files / Skip."], ["Skip 1 time — Bỏ qua 1 lần", "Bỏ qua trong một lần Chạy tất cả của phiên PIP hiện tại; lựa chọn này được xóa sau lượt chạy."], ["Hủy bỏ qua hoặc chấp nhận", "Undo skip khôi phục yêu cầu dùng mục đó. Browse thành công cũng hủy bỏ qua. Với file sai EP đã nhận ra, tick chấp nhận để dùng tên local đã chỉnh; bỏ tick để hủy."], ["Recheck — Kiểm tra lại", "Chọn file xong thì kiểm tra lại và tiếp tục để tạo lại EP và lịch. Các lỗi chưa giải quyết vẫn được báo."]]], "content": ["Sửa nội dung EP / Khóa / Thêm file", [["Mở khóa trước khi sửa", "Dòng có sẵn mặc định khóa. Chọn dòng, mở khóa rồi sửa hoặc nhấp đúp. Khóa chỉ ngăn sửa dòng, không cố định vị trí phát."], ["Chọn file hoặc nhập thời lượng", "Có file thì chọn file nguồn. Chưa có thì nhập thời lượng để tạo temp lên lịch. Có thể thêm part như AP PARTD, không bắt buộc số part cố định."], ["Loại và vị trí", "Chọn Show, Teaser, ADS ưu tiên hoặc ADS thường. Khi tự đặt vị trí, chọn block, mục làm mốc, trước/sau và các cycle áp dụng. Xem lại thứ tự ở Cycle 1 và Các cycle."], ["Khôi phục và lưu", "Khôi phục mặc định đưa dòng gốc về thông tin nhận diện ban đầu. Xóa dùng cho dòng tự thêm; muốn bỏ ADS hoặc teaser thì dùng Files / Skip. Lưu áp dụng cho EP này; Hủy giữ dữ liệu đã lưu trước đó."]]], "names": ["Tên nguồn / Tên local / Max", [["Sửa tên local", "Nhấp đúp ô tên local, sửa rồi bấm Lưu tên đã sửa. Giữ đúng số EP, mã show, part/segment và dấu phiên bản cần thiết. Tên nguồn giữ nguyên."], ["Rút gọn tên", "Tên người dùng quy tắc rút gọn hiện có. Tiêu đề show khác lấy tối đa 5 từ đầu, giữ part và segment. Quét và tạo lại EP/lịch để dùng tên mới."], ["Max và No Max", "Giữ phân biệt hai bản. Ô Max áp dụng cho những dòng nhập thời lượng được hỗ trợ. Chọn đúng bản mà thời lượng đang mô tả; bộ canh giờ sẽ dùng bản phù hợp."], ["Phiên bản AP", "Mỗi part AP lấy phiên bản mới nhất; nếu cùng phiên bản thì xét thời gian sửa file. Max và No Max được chọn riêng. Lịch dùng bản phù hợp, không phát liên tiếp cả hai."]]], "cycles": ["Cycle 1 / Các cycle / M3U", [["Cycle 1", "Kiểm tra show mở đầu, thứ tự chương trình, các segment và mục chèn trước khi so các cycle sau."], ["Các cycle và màu", "Xem thứ tự cả ngày và cột thời gian. Show màu trắng. Teaser, ADS cố định, ADS ngày, ADS thêm và mục đặc biệt có màu riêng. Cảnh báo màu vàng. Đọc cả tên và QC để biết vấn đề cụ thể."], ["Chèn giữa segment", "Teaser hợp lệ dài hơn 2 phút vẫn có thể chèn giữa segment. ADS thường ở khe này phải dưới 2 phút. Mỗi khe có một mục chèn."], ["File lịch M3U", "M3U xuất vào thư mục _playlist local; đường dẫn cụ thể nằm trong báo cáo. Xem QC trước khi gửi. File local là temp lên lịch; dùng Chuẩn bị file để copy video gốc."]]], "qc": ["QC lịch vừa tạo", [["Mốc giờ", "Kiểm tra giờ và vị trí MT, sau đó giờ cuối ngày và show cuối. Dung sai thông thường ±15 giây. Ngoại lệ cuối ngày được nêu trong báo cáo."], ["ADS theo ngày — mục 3", "DO NOT SKIP trên cùng, tiếp theo ADS ưu tiên rồi ADS thường. Cycle có dùng hiện xanh, không dùng hiện đỏ. ADS thường đủ ít nhất 3 cycle hiện xanh; dưới 3 hiện đỏ. Xem thêm ngoại lệ canh giờ và lỗi còn lại."], ["Các mục cần xử lý — mục 4", "Đọc tên file và lỗi cụ thể. Chọn/thêm đúng file, sửa INPUT hoặc thiết lập liên quan rồi tạo lại lịch. Thiếu ADS đã nêu trong danh sách ADS ngày không nhắc lại ở đây."], ["Điều chỉnh và kết quả", "Báo cáo ghi các lần đổi Max, thêm/bớt mục để canh giờ và đường dẫn kết quả. Đối chiếu thêm Cycle 1 và Các cycle."]]], "external": ["Kiểm tra lịch ngoài — M3U hoặc Word", [["Chọn đúng loại hướng dẫn", "vMix check: kiểm tra file lịch M3U. EP list check: kiểm tra danh sách EP trong Word DOCX. Cả hai mở từ Check external schedule. Chọn mục tương ứng trong danh mục hướng dẫn để xem các bước ngắn gọn."], ["Chọn lịch", "Bấm Check external schedule, chọn M3U hoặc Word DOCX của người khác. Kiểm tra số EP; nạp hoặc nhập câu show mở đầu từ bước 0."], ["Bắt đầu kiểm tra", "Đối chiếu lịch với INPUT và quy tắc. Câu show mở đầu thiếu hoặc chưa rõ thì sửa lại. Nếu bỏ qua xác nhận, vẫn hiện QC nhưng chưa xác nhận được thứ tự mở đầu đúng."], ["Những gì được kiểm tra", "Show mở đầu, quy tắc cố định, ADS theo cycle, show/teaser/FN bất thường và khác biệt so với Cycle 1. Word được ghi gộp S1A/S1B/S1C. Tên đối chiếu theo số EP, mã, một phần tên và part."], ["Phạm vi và báo cáo", "Mặc định không kiểm tra mốc MT/24 giờ hoặc đo thời lượng. Đọc báo cáo ngay trong PIP. Save report lưu báo cáo; nút lên đầu giúp quay về đầu trang."]]], "check_m3u": ["vMix check — kiểm tra M3U", [["1. Chọn file lịch", "Bấm Check external schedule → Chọn M3U / Word. Chọn file M3U cần kiểm tra và xem số EP đã nhận có đúng không."], ["2. Show mở đầu", "Nạp câu show mở đầu từ bước 0; nếu chưa có thì dán vào. Kiểm tra câu đó đúng EP đang check."], ["3. Bắt đầu kiểm tra", "Bấm nút bắt đầu check. Đọc QC ngay trong PIP: show mở đầu, quy tắc cố định, ADS ngày, show/teaser/FN và khác biệt giữa các cycle. Đây là kiểm tra file M3U, không đọc trực tiếp ứng dụng vMix đang chạy. Mặc định không check mốc MT/24 giờ hoặc đo thời lượng."]]], "check_docx": ["EP list check — kiểm tra Word", [["1. Chọn danh sách EP", "Bấm Check external schedule → Chọn M3U / Word. Chọn file Word DOCX chứa danh sách EP và kiểm tra số EP."], ["2. Show mở đầu", "Nạp câu show mở đầu từ bước 0; nếu chưa có thì dán vào."], ["3. Bắt đầu kiểm tra", "Bấm nút bắt đầu check rồi đọc QC trong PIP. Đối chiếu nội dung ghi trong Word với INPUT và quy tắc. NWN S1A/S1B/S1C được ghi gộp. Cycle sau theo Cycle 1 và những thay đổi ghi trong Word; chỗ ghi chưa rõ cần xác nhận. Mặc định không check mốc MT/24 giờ hoặc đo thời lượng."]]], "update": ["Cập nhật PIP / Ngôn ngữ / Gửi bộ", [["Cập nhật temp ADS", "Bấm Cập nhật temp ADS ở thanh bên. Dùng INPUT hiện tại hoặc bấm Chọn INPUT để chọn bảng mới; chương trình đọc danh sách INPUT_4. Bấm cập nhật để tạo temp còn thiếu trong @ ADS 2. File đã có được giữ nguyên. Thiếu thời lượng hoặc tên chưa rõ sẽ báo cần kiểm tra. Nếu đã đủ và không có mục cần kiểm tra thì báo: Danh sách không có gì mới."], ["Update PIP", "Cập nhật phần mềm từ Hub. Chờ công việc đang chạy xong rồi cập nhật theo thông báo. Nút này khác Update cạnh Chuẩn bị file, vốn cập nhật video đã copy."], ["Ngôn ngữ", "Chọn ngôn ngữ ở thanh bên; PIP nhớ cho lần mở sau. Hướng dẫn mặc định theo lựa chọn đó. Có thể chuyển Tiếng Việt / English ngay trong cửa sổ hướng dẫn mà không đổi ngôn ngữ phần mềm."], ["Gửi cho người khác", "Gửi toàn bộ ZIP portable: có phần mềm, môi trường chạy, INPUT và file ADS/mẫu nhẹ. Máy nhận vẫn cần truy cập nguồn video gốc. Update PIP cập nhật chương trình/INPUT đã công bố, không tải cả thư viện ADS."], ["Hướng dẫn và Thứ tự xử lý", "Bấm ⓘ cạnh nhóm nút để đọc cách dùng. Nút User Guide mở toàn bộ hướng dẫn. Thứ tự xử lý PIP giải thích các quy tắc và ưu tiên đang áp dụng."]]]}')
